let selectedDays = max_of(datetime_diff('second', {TimeRange:end}, {TimeRange:start}) / 86400.0, 1.0);
let avgDailyGB = toreal(coalesce(toscalar(union withsource = SourceTableName * | where TimeGenerated between ({TimeRange:start} .. {TimeRange:end}) | where _IsBillable == true | summarize sum(_BilledSize) / 1024.0 / 1024.0 / 1024.0 / selectedDays), 0.0));
let tierLevels = dynamic([100,200,300,400,500,1000,2000,5000]);
print AvgDailyIngestionGB = avgDailyGB, TierLevels = tierLevels
| mv-expand TierLevel = TierLevels to typeof(int)
| extend Eligible = TierLevel >= AvgDailyIngestionGB
| summarize RecommendedTierGBPerDay = minif(TierLevel, Eligible), MaxTierGBPerDay = max(TierLevel), AvgDailyIngestionGB = any(AvgDailyIngestionGB)
| project ['Average Billable Daily Ingestion (GB)'] = round(AvgDailyIngestionGB, 2), ['Recommended commitment tier'] = iif(isnotempty(RecommendedTierGBPerDay), strcat(tostring(RecommendedTierGBPerDay), ' GB/day'), strcat('Above ', tostring(MaxTierGBPerDay), ' GB/day — review Enterprise Agreement options'))
